@use "sass:color";

@import url('https://fonts.googleapis.com/css2?family=Nunito+Sans&display=swap');

$primary: #C7C402;
$secondary: #C7C402;
$gray-100: #e8e8e8;
$gray-200: #d1d1d1;
$gray-300: #bbbbbb;
$gray-400: #a4a4a4;
$gray-500: #8D8D8D;
$gray-600: #717171;
$gray-700: #555555;
$gray-800: #383838;
$gray-900: #1c1c1c;
$black: #090909;
$white: #ffffff;

$text-muted: $gray-500;

$body-bg: $white;

$link-decoration: underline;
$link-color: $gray-500;

$input-font-weight: 400;
$input-color: $primary;
$input-bg: $white;
$input-border-color: $primary;
$input-focus-border-color: color.adjust($primary, $lightness: -5%, $space: hsl);
$input-btn-focus-box-shadow:  0 0 15px 0.2em rgba($input-focus-border-color, 0.25);

$component-active-bg: $secondary;
$custom-select-color: $gray-800;
$custom-select-border-width: 0;
$input-btn-padding-x-sm: 0.9rem;
$input-btn-padding-y-sm: 0.4rem;

$input-padding-x: 1.3rem;
$input-padding-y: .8rem;

$font-family-sans-serif: 'Nunito Sans', monospace;
$font-size-base: 0.85rem;
$input-font-size: 1.4rem;
$lead-font-size: $font-size-base * 1.1;

$input-font-weight: 400;
$headings-font-weight: 700;
$display-font-weight: 700;
$font-weight-bolder: 600;

$border-radius: 0px;

$badge-font-size: 75%;
$badge-font-weight: 300;
$badge-pill-padding-x: 1.5em;
$badge-padding-y: 0.75em;

$enable-rounded: false;
$enable-responsive-font-sizes: true;

@import "~bootstrap/scss/bootstrap";

.font-letter-spacing-tight {
  letter-spacing: -0.05rem;
}

input[type=search] {
  letter-spacing: -0.05em;
}

a {
  text-decoration: underline !important;
}

.form-control-secondary {
  color: $secondary;
  border-color: $secondary;

  &:focus {
    color: $secondary;
    border-color: $secondary;
    box-shadow: 0 0 15px 0.2em rgba($secondary, 0.35);
  }
}

.text-dark-2 {
  color: $gray-600;
}

.navbar-toggler-icon {
  background-size: 75% 75%;
}

// For loading indicator svg
.stroke-primary {
  stroke: $primary;
}

.border-width-2 {
  border-width: 2px;
}

.border-none {
  border: 0;
  box-shadow: none; /* You may want to include this as bootstrap applies these styles too */
}

.navbar-light .navbar-toggler-icon {
  background-image: url('~images/refine_icon.svg');
}

require('dotenv').config();

const Typesense = require('typesense');

module.exports = (async () => {
  // Create a client
  const typesense = new Typesense.Client({
    nodes: [
      {
        host: process.env.TYPESENSE_HOST,
        port: process.env.TYPESENSE_PORT,
        protocol: process.env.TYPESENSE_PROTOCOL,
      },
    ],
    apiKey: [REDACTED],
    connectionTimeoutSeconds: 60 * 60,
  });

  const schema = {
    name: 'products',
    num_documents: 0,
    fields: [
      {
        name: 'name',
        type: 'string',
        facet: false,
      },
      {
        name: 'description',
        type: 'string',
        facet: false,
      },
      {
        name: 'brand',
        type: 'string',
        facet: true,
      },
      {
        name: 'categories',
        type: 'string[]',
        facet: true,
      },
      {
        name: 'categories.lvl0',
        type: 'string[]',
        facet: true,
      },
      {
        name: 'categories.lvl1',
        type: 'string[]',
        facet: true,
        optional: true,
      },
      {
        name: 'categories.lvl2',
        type: 'string[]',
        facet: true,
        optional: true,
      },
      {
        name: 'categories.lvl3',
        type: 'string[]',
        facet: true,
        optional: true,
      },
      {
        name: 'price',
        type: 'float',
        facet: true,
      },
      {
        name: 'popularity',
        type: 'int32',
        facet: false,
      },
      {
        name: 'free_shipping',
        type: 'bool',
        facet: true,
      },
      {
        name: 'rating',
        type: 'int32',
        facet: true,
      },
      {
        name: 'vectors',
        type: 'float[]',
        num_dim: 384,
      },
      // This is a field that exists in the document, but we only want to use it for display purposes and not search purposes.
      // So we can just leave it off the schema, but still send it in the document.
      // These fields are considered un-indexed fields, and stored on disk and returned when the document is a hit.
      // These un-indexed fields do not count towards RAM usage.
      // {
      //   name: 'image',
      //   type: 'string',
      //   facet: false,
      // },
    ],
    default_sorting_field: 'popularity',
  };

  console.log('Populating index in Typesense');

  const products = require('./data/ecommerce-with-vectors.json');

  let reindexNeeded = false;
  try {
    const collection = await typesense.collections('products').retrieve();
    console.log('Found existing schema');
    // console.log(JSON.stringify(collection, null, 2));
    if (
      collection.num_documents !== products.length ||
      process.env.FORCE_REINDEX === 'true'
    ) {
      console.log('Deleting existing schema');
      reindexNeeded = true;
      await typesense.collections('products').delete();
    }
  } catch (e) {
    reindexNeeded = true;
  }

  if (!reindexNeeded) {
    return true;
  }

  console.log('Creating schema: ');
  console.log(JSON.stringify(schema, null, 2));
  await typesense.collections().create(schema);

  // const collectionRetrieved = await typesense
  //   .collections("products")
  //   .retrieve();
  // console.log("Retrieving created schema: ");
  // console.log(JSON.stringify(collectionRetrieved, null, 2));

  console.log('Adding records: ');

  // Bulk Import
  products.forEach((product) => {
    product.free_shipping = product.name.length % 2 === 1; // We need this to be deterministic for tests
    product.rating = (product.description.length % 5) + 1; // We need this to be deterministic for tests
    product.categories.forEach((category, index) => {
      product[`categories.lvl${index}`] = [
        product.categories.slice(0, index + 1).join(' > '),
      ];
    });
  });

  try {
    const returnData = await typesense
      .collections('products')
      .documents()
      .import(products);
    console.log(returnData);
    console.log('Done indexing.');

    const failedItems = returnData.filter((item) => item.success === false);
    if (failedItems.length > 0) {
      throw new Error(
        `Error indexing items ${JSON.stringify(failedItems, null, 2)}`
      );
    }

    return returnData;
  } catch (error) {
    console.log(error);
  }
})();

import { debounce } from 'lodash';
import jQuery from 'jquery';
import * as bootstrap from 'bootstrap';

window.$ = jQuery; // workaround for https://github.com/parcel-bundler/parcel/issues/333

import instantsearch from 'instantsearch.js/es';
import {
  searchBox,
  pagination,
  refinementList,
  hits,
  stats,
  sortBy,
  hierarchicalMenu,
  rangeSlider,
  ratingMenu,
  toggleRefinement,
  hitsPerPage,
  clearRefinements,
} from 'instantsearch.js/es/widgets';
import { history } from 'instantsearch.js/es/lib/routers';
import TypesenseInstantSearchAdapter from 'typesense-instantsearch-adapter';

let TYPESENSE_SERVER_CONFIG = {
  apiKey: [REDACTED], // Be sure to use an API key that only allows searches, in production
  nodes: [
    {
      host: process.env.TYPESENSE_HOST,
      port: process.env.TYPESENSE_PORT,
      protocol: process.env.TYPESENSE_PROTOCOL,
    },
  ],
  connectionTimeoutSeconds: 5,
  numRetries: 8,
};

// [2, 3].forEach(i => {
//   if (process.env[`TYPESENSE_HOST_${i}`]) {
//     TYPESENSE_SERVER_CONFIG.nodes.push({
//       host: process.env[`TYPESENSE_HOST_${i}`],
//       port: process.env.TYPESENSE_PORT,
//       protocol: process.env.TYPESENSE_PROTOCOL,
//     });
//   }
// });

// Unfortunately, dynamic process.env keys don't work with parcel.js
// So need to enumerate each key one by one

if (process.env[`TYPESENSE_HOST_2`]) {
  TYPESENSE_SERVER_CONFIG.nodes.push({
    host: process.env[`TYPESENSE_HOST_2`],
    port: process.env.TYPESENSE_PORT,
    protocol: process.env.TYPESENSE_PROTOCOL,
  });
}

if (process.env[`TYPESENSE_HOST_3`]) {
  TYPESENSE_SERVER_CONFIG.nodes.push({
    host: process.env[`TYPESENSE_HOST_3`],
    port: process.env.TYPESENSE_PORT,
    protocol: process.env.TYPESENSE_PROTOCOL,
  });
}

if (process.env[`TYPESENSE_HOST_NEAREST`]) {
  TYPESENSE_SERVER_CONFIG['nearestNode'] = {
    host: process.env[`TYPESENSE_HOST_NEAREST`],
    port: process.env.TYPESENSE_PORT,
    protocol: process.env.TYPESENSE_PROTOCOL,
  };
}

const typesenseInstantsearchAdapter = new TypesenseInstantSearchAdapter({
  server: TYPESENSE_SERVER_CONFIG,
  additionalSearchParameters: {
    // The following parameters are directly passed to Typesense's search API endpoint.
    //  So you can pass any parameters supported by the search endpoint below.
    //  queryBy is required.
    query_by: 'name,categories,description',
    query_by_weights: '4,2,1',
    num_typos: 1,
    typo_tokens_threshold: 1,
    exclude_fields: 'vectors',
    // By default, Typesense approximates facet counts for performance.
    // Turning on exhaustive search will get you accurate facet counts, at the cost of a slight performance hit.
    exhaustive_search: true,
    // group_by: "categories",
    // group_limit: 1
    // pinned_hits: "23:2"
  },
});
const searchClient = typesenseInstantsearchAdapter.searchClient;
const search = instantsearch({
  searchClient,
  indexName: 'products',
  routing: {
    router: history({ cleanUrlOnDispose: true }),
  },
  future: {
    preserveSharedStateOnUnmount: true,
  },
});

// ============ Begin Widget Configuration
search.addWidgets([
  searchBox({
    container: '#searchbox',
    showSubmit: false,
    showReset: false,
    placeholder: 'Search for products... ',
    autofocus: false,
    cssClasses: {
      input: 'form-control form-control-sm border border-light text-dark',
      loadingIcon: 'stroke-primary',
    },
  }),
  pagination({
    container: '#pagination',
    cssClasses: {
      list: 'd-flex flex-row justify-content-end',
      item: 'px-2 d-block',
      link: 'text-decoration-none',
      disabledItem: 'text-muted',
      selectedItem: 'fw-bold text-primary',
    },
  }),
  refinementList({
    limit: 10,
    showMoreLimit: 50,
    container: '#brand-list',
    attribute: 'brand',
    searchable: true,
    searchablePlaceholder: 'Search brands',
    showMore: true,
    sortBy: ['name:asc', 'count:desc'],
    cssClasses: {
      searchableInput:
        'form-control form-control-sm form-control-secondary mb-2 border-light-2',
      searchableSubmit: 'd-none',
      searchableReset: 'd-none',
      showMore: 'btn btn-secondary btn-sm',
      list: 'list-unstyled',
      count: 'badge text-dark-2 ms-2',
      label: 'd-flex align-items-center',
      checkbox: 'me-2',
    },
  }),
  hierarchicalMenu({
    container: '#categories-hierarchical-menu',
    showParentLevel: true,
    rootPath: 'Cell Phones',
    attributes: [
      'categories.lvl0',
      'categories.lvl1',
      'categories.lvl2',
      'categories.lvl3',
    ],
    cssClasses: {
      showMore: 'btn btn-secondary btn-sm',
      list: 'list-unstyled',
      childList: 'ms-4',
      count: 'badge text-dark-2 ms-2',
      link: 'text-dark text-decoration-none',
      selectedItem: 'text-primary fw-bold',
      parentItem: 'text-dark fw-bold',
    },
  }),
  toggleRefinement({
    container: '#toggle-refinement',
    attribute: 'free_shipping',
    templates: {
      labelText: () => 'Free shipping',
    },
    cssClasses: {
      label: 'd-flex align-items-center',
      checkbox: 'me-2',
    },
  }),
  rangeSlider({
    container: '#price-range-slider',
    attribute: 'price',
  }),
  ratingMenu({
    container: '#rating-menu',
    attribute: 'rating',
    cssClasses: {
      list: 'list-unstyled',
      link: 'text-decoration-none',
      starIcon: '',
      count: 'badge text-dark-2 ms-2',
      disabledItem: 'text-muted',
      selectedItem: 'fw-bold text-primary',
    },
  }),
  sortBy({
    container: '#sort-by',
    items: [
      { label: 'Relevancy', value: 'products' },
      { label: 'Price (asc)', value: 'products/sort/price:asc' },
      { label: 'Price (desc)', value: 'products/sort/price:desc' },
    ],
    cssClasses: {
      select: 'form-select form-select-sm border-none text-black',
    },
  }),
  hits({
    container: '#hits',
    templates: {
      item: (hit, { html, components }) => html`
        <div>
            <div class="row image-container">
                <div class="col-md d-flex align-items-end justify-content-center">
                    <img src="${hit.image}" alt="${hit.name}" />
                </div>
            </div>
            <div class="row mt-5">
                <div class="col-md">
                    <h5>${components.Highlight({ hit, attribute: 'name' })}</h5>
                </div>
            </div>

            <div class="row mt-2">
                <div class="col-md">${components.Highlight({
                  hit,
                  attribute: 'description',
                })}</div>
            </div>

            <div class="row mt-auto">
              <div class="col-md">
                <div class="hit-price fw-bold mt-4">\$${hit.price}</div>
                <div class="hit-rating">Rating: ${hit.rating}/5</div>
              </div>
            </div>

            <div class="row mt-auto">
                <div class="col-md">
                  <a href="#" data-document-id="${hit.id}" onclick="${() =>
        findSimilarProducts(hit.id)}">Find Similar</a>
                </div>
            </div>
        </div>
      `,
    },
    cssClasses: {
      list: 'list-unstyled grid-container',
      item: 'd-flex flex-column search-result-card mb-1 me-1 p-3',
      loadMore: 'btn btn-primary mx-auto d-block mt-4',
      disabledLoadMore: 'btn btn-dark mx-auto d-block mt-4',
    },
  }),
  hitsPerPage({
    container: '#hits-per-page',
    items: [
      { label: '9 per page', value: 9, default: true },
      { label: '18 per page', value: 18 },
    ],
    cssClasses: {
      select: 'form-select form-select-sm border-none text-black',
    },
  }),
  stats({
    container: '#stats',
    templates: {
      text: (
        { nbHits, hasNoResults, hasOneResult, processingTimeMS },
        { html }
      ) => {
        let statsText = '';
        if (hasNoResults) {
          statsText = 'No results';
        } else if (hasOneResult) {
          statsText = '1 result';
        } else {
          statsText = `${nbHits.toLocaleString()} products`;
        }
        return html`${statsText} found in ${processingTimeMS}ms`;
      },
    },
    cssClasses: {
      text: 'small',
    },
  }),
  clearRefinements({
    container: '#clear-refinements',
    cssClasses: {
      button: 'btn btn-primary',
    },
  }),
]);

window.sendEventDebounced = debounce((uiState) => {
  window.gtag('event', 'page_view', {
    page_path: window.location.pathname + window.location.search,
  });
}, 500);

search.use(() => ({
  onStateChange({ uiState }) {
    window.sendEventDebounced(uiState);
  },
  subscribe() {},
  unsubscribe() {},
}));

search.start();

window.findSimilarProducts = async function (productId) {
  const results = await typesenseInstantsearchAdapter.typesenseClient
    .collections('products')
    .documents()
    .search({
      q: '*',
      per_page: 4,
      vector_query: `vectors:([], id: ${productId})`,
    });
  console.log(results);

  const modalContent = results.hits.map((hit) => {
    return `
      <div class="p-3 m-3 border-1">
        <div class="row image-container">
            <div class="col-md d-flex align-items-end justify-content-center">
                <img src="${hit.document.image}" alt="${hit.document.name}" />
            </div>
        </div>
        <div class="row mt-5">
            <div class="col-md">
                ${hit.document.name}
            </div>
        </div>
      </div>
    `;
  });

  $('#similar-products-modal .modal-body .similar-products').html(modalContent);
  const modal = new bootstrap.Modal('#similar-products-modal', {});
  modal.show();
};
